import math, bisect, heapq, os
from collections import Counter, defaultdict, deque
from itertools import groupby

class TN:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def build(a):
    if not a or a[0] is None:
        return None
    root = TN(a[0]); q = deque([root]); i = 1
    while q and i < len(a):
        node = q.popleft()
        if i < len(a) and a[i] is not None:
            node.left = TN(a[i]); q.append(node.left)
        i += 1
        if i < len(a) and a[i] is not None:
            node.right = TN(a[i]); q.append(node.right)
        i += 1
    return root

def ser(root):
    out = []; q = deque([root])
    while q:
        n = q.popleft()
        if n is None:
            out.append(None); continue
        out.append(n.val); q.append(n.left); q.append(n.right)
    while out and out[-1] is None:
        out.pop()
    return out

def ins(root, v):
    if root is None:
        return TN(v)
    if v < root.val:
        root.left = ins(root.left, v)
    else:
        root.right = ins(root.right, v)
    return root

def adj_from_edges(n, edges):
    g = [[] for _ in range(n)]
    for a, b in edges:
        g[a].append(b); g[b].append(a)
    return g

ROMAN = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

def reorganizeString(s):
    counts = Counter(s)
    max_freq = max(counts.values())
    if max_freq > (len(s) + 1) // 2:
        return ""
    # Arrange characters so no adjacent are same
    max_heap = [(-cnt, char) for char, cnt in counts.items()]
    heapq.heapify(max_heap)
    res = []
    prev_cnt, prev_char = 0, ""
    while max_heap:
        cnt, char = heapq.heappop(max_heap)
        res.append(char)
        if prev_cnt < 0:
            heapq.heappush(max_heap, (prev_cnt, prev_char))
        prev_cnt = cnt + 1
        prev_char = char
    return "".join(res)
